function toggleSonar(){if(!isSonarUnlocked(journal)){hud.toast('The fish finder unlocks after twelve fish in the journal.',4000);return false;}sonar.on=!sonar.on;sonarCanvas.classList.toggle('show',sonar.on);hud.toast(sonar.on?'Fish finder on.':'Fish finder off.',2000);return sonar.on;}
function stepSonar(dt){if(!sonar.on||!sonarCtx)return;const k=kayak.state;const depth=Math.max(0,-bathy.height(k.x,k.z));const fish=pop.fish.map(f=>({x:f.brain.x,z:f.brain.z,depth:-f.brain.y}));if(tickSonar(sonar,dt,{depth,tempF:waterTempF(dayOfYear(clock.ms)),fish,kayak:{x:k.x,z:k.z}}))drawSonar(sonar,sonarCtx,sonarCanvas.width,sonarCanvas.height);}
// --- First Morning with Ray: the guided first ten minutes, skippable; the lake cannot promise a bite, so the lesson arranges one
let tutorial=null,tutorialEvents=[];
let tutorialHubOpen=false;
function tutEvent(type){if(tutorial)tutorialEvents.push(type);}
function touchUI(){return !!(touch&&touch.wanted&&document.body.classList.contains('touch-active'));}
function lessonsDone(){if(!settings.tutorialLessons||typeof settings.tutorialLessons!=='object')settings.tutorialLessons={};return settings.tutorialLessons;}
function tutorialTitle(){if(!tutorial)return;const l=lessonById(tutorial.lesson);const n=LESSONS.indexOf(l)+1;document.getElementById('tutTitle').textContent=`LESSON ${n} · ${l.title.toUpperCase()} · ${Math.min(tutorial.index+1,l.steps.length)}/${l.steps.length}`;}
function startTutorial(lessonId='morning'){const lesson=lessonById(lessonId)||LESSONS[0];if(mode==='demo')takeRod();if(mode==='map')closeMap();if(mode==='photo')closePhoto();if(mode==='replay')closeReplay();if(mode==='aquarium')stopAquarium();if(session&&!session.closed)closeCurrentSession();closeTutorialHub();
 if(angling.state.phase!=='idle')angling.reelIn();if(angling.holderState(simTime)){angling.takeHolder(simTime);angling.reelIn();}
 tutorial=createTutorial(lesson.id);tutorial.spokenStep=-1;tutorialEvents=[];const su=lesson.setup;angling.setRig(Math.max(0,RIGS.findIndex(r=>r.id===su.rig)));setWeather(su.weather||'calm');setHour(clock,su.hour);setRate('4');setPolarized(!!su.polarized);kayak.state.anchored=su.anchored!==false;cameraMode='surface';hud.hideCard();hud.hideSessionCard();start();tutorialTitle();document.getElementById('tutorialBar').classList.remove('hidden');hud.toast(lesson.title+'. Skip a step or leave the lesson from the bar at the top right.',6000);return tutorial;}
function finishTutorial(){const t=tutorial;if(!t)return;const skipped=t.skipped;const lesson=lessonById(t.lesson);tutorial=null;hud.setCaption('');document.getElementById('tutorialBar').classList.add('hidden');
 if(skipped){saveSettings(settings);hud.toast('Left the lesson. The lake is yours.',5000);return;}
 lessonsDone()[lesson.id]=true;const sum=lessonSummary(lessonsDone());settings.tutorialDone=true;saveSettings(settings);const next=sum.next?lessonById(sum.next):null;
 hud.toast(next?`${lesson.title}: done. Next up, ${next.title}, under Tutorial on the menu.`:'Every lesson done. The lake is yours.',7000);
 voice.speak(next?{id:'tut-done-lesson',text:"That's the lesson. Come back for the next one when you're ready.",file:'assets/voice/tut-done-lesson.mp3',priority:6}:{id:'tut-done-course',text:"That's the lot. Nothing left I can teach you from this seat. Go fish.",file:'assets/voice/tut-done-course.mp3',priority:6});}
function skipTutorialNow(){if(!tutorial)return false;skipTutorial(tutorial);finishTutorial();return true;}
function skipTutorialStepNow(){if(!tutorial)return false;tutorialSkipStep(tutorial);tutorial.helperAt=null;if(tutorial.done)finishTutorial();else tutorialTitle();return true;}
function openTutorialHub(){if(mode==='demo')takeRod();if(mode==='aquarium')stopAquarium();if(mode==='map')closeMap();if(mode==='photo')closePhoto();if(mode==='playing'){mode='menu';keys={};touch?.setActive(false);hud.showMenu({eyebrow:'AT ANCHOR',title:'Take a<br>breath',description:'The lake keeps moving while the menu is open.',button:'Back to the water'});}renderTutorialHub();document.getElementById('tutorialPanel').classList.remove('hidden');tutorialHubOpen=true;return true;}
function closeTutorialHub(){document.getElementById('tutorialPanel').classList.add('hidden');tutorialHubOpen=false;}
function renderTutorialHub(){const sum=lessonSummary(lessonsDone());document.getElementById('lessonList').innerHTML=sum.rows.map((r,i)=>`<button class="lesson${r.done?' done':''}${r.id===sum.next?' next':''}" data-lesson="${r.id}"><span class="num">${r.done?'✓':i+1}</span><span class="body"><b>${r.title}</b><small>${r.blurb}</small></span><span class="meta">${r.done?'DONE':r.minutes+' MIN'}${r.id===sum.next?' · NEXT':''}</span></button>`).join('');document.getElementById('lessonLine').textContent=sum.completed>=sum.total?'Every lesson done. Play any of them again.':sum.completed?`${sum.completed} of ${sum.total} lessons done. Ray sets the boat up for each one.`:'Five short lessons. Ray sets the boat up for each one and watches what you do.';}
function stepTutorialFrame(dt){if(!tutorial||tutorial.done||mode!=='playing')return;const hs=angling.holderState(simTime);const r=stepTutorial(tutorial,{phase:angling.state.phase,casts:angling.state.castCount,technique:angling.state.label,polarized:polarizedTarget>0,rigId:angling.rig().id,onBottom:!!angling.line.lureOnBottom,holder:!!hs,anchored:!!kayak.state.anchored,lureCam:cameraMode==='lurecam',dt,events:tutorialEvents});tutorialEvents=[];if(r.finished){finishTutorial();return;}hud.setCaption(touchUI()?r.touch:r.text);
 if(tutorial.spokenStep!==tutorial.index){tutorial.spokenStep=tutorial.index;tutorialTitle();voice.speak({id:'tut-'+tutorial.lesson+'-'+r.id,text:r.say,file:stepClip(tutorial.lesson,r.id),priority:6});}
 if(r.needsFish&&angling.state.phase==='retrieve'&&tutorial.helperAt===null)tutorial.helperAt=simTime+4;
 if(r.needsFish&&tutorial.helperAt!==null&&simTime>=tutorial.helperAt&&angling.state.phase==='retrieve'){const lp=angling.lure();const sp=tutorial.lesson==='rigs'?SPECIES.bluegill:SPECIES.largemouth;const f=pop.spawn(lp.x+1.2,lp.z+.8,sp===SPECIES.bluegill?.21:.42,.95,null,sp);if(f){tutorial.helperAt=null;tutorial.helperUsed++;f.brain.state='STRIKE';f.brain.stateTime=0;f.brain.strikeReady=simTime+.3;f.brain.refuseUntil=-1;}else tutorial.helperAt=simTime+2;}
 if(r.needsHolderBite&&hs&&!hs.bite&&tutorial.helperAt===null)tutorial.helperAt=simTime+7;
 if(r.needsHolderBite&&tutorial.helperAt!==null&&simTime>=tutorial.helperAt&&hs&&!hs.bite){const hb=angling.holderTarget();const f=hb?pop.spawn(hb.x,hb.z,.52,.9,null,SPECIES.catfish):null;if(f){f.brain.x=hb.x+.12;f.brain.y=hb.y;f.brain.z=hb.z;f.brain.targetKind='holder';f.brain.state='BITE';f.brain.stateTime=0;tutorial.helperAt=null;tutorial.helperUsed++;}else tutorial.helperAt=simTime+2;}}
// --- Photo mode and the share card: a free orbit around the kayak, and the rendered frame with the catch written on it
let lastCatchCard=null,photoFrom='menu';const photo={yaw:2.6,pitch:.16,dist:6,drag:null};
function snapshotFrame(){render();const img=new Image();img.src=renderer.domElement.toDataURL('image/jpeg',.92);return new Promise(res=>{img.onload=()=>res(img);img.onerror=()=>res(null);});}
async function savePhoto(kind='photo',{download=true}={}){const img=await snapshotFrame();const lines=kind==='catch'&&lastCatchCard?catchCardLines(lastCatchCard):photoCardLines({place:'Three Mile Run',time:formatClock(clock.ms),date:formatDate(clock.ms),weather:WEATHER[weatherName].label});const cv=composeCard(img,lines);const blob=await cardBlob(cv);const how=await deliver(blob,fileName(kind,kind==='catch'?lastCatchCard:null),{download});hud.toast(how==='shared'?'Shared.':how==='downloaded'?'Photo saved.':'Photo ready.',2500);return {how,bytes:blob.size,w:cv.width,h:cv.height,dataUrl:download?null:cv.toDataURL('image/jpeg',.85)};}
function openPhoto(){if(mode==='photo')return;if(mode==='demo')takeRod();photoFrom=mode==='playing'?'playing':'menu';mode='photo';tutEvent('photo_open');keys={};pressed={};touch?.setActive(false);hud.hideMenu();hud.hideCard();document.body.classList.add('photo');document.getElementById('photoBar').classList.remove('hidden');cameraMode='photo';photo.drag=null;}
function closePhoto(){if(mode!=='photo')return;tutEvent('photo_close');document.body.classList.remove('photo');document.getElementById('photoBar').classList.add('hidden');cameraMode='surface';if(photoFrom==='playing')start();else{mode='menu';hud.showMenu({});}}
// --- First Light sessions: twenty real minutes on a daily seed with a target species, scored to the fleet's board
let session=null,sessionCasts0=0,sessionBoardMe=null,cardPost=null;
// --- Big Bass: best five bass by length against three rival kayaks driven by the planner's own numbers
let tourney=null,rivalBoats=[],tourneyToastAt=-99;
function placeRival(i,spot){const b=rivalBoats[i];if(!b||!spot)return;const R=(spot.r||6)+5;for(let k=0;k<8;k++){const a=k/8*Math.PI*2+tourney.random()*.4;const x=spot.x+Math.cos(a)*R,z=spot.z+Math.sin(a)*R;if(bathy.height(x,z)<-.6){b.place(x,z,tourney.random()*6.28);return;}}b.place(spot.x,spot.z,0);}
function updateTourneyBar(){if(!tourney)return;hud.setSession({html:`Big Bass · <b>${Math.min(5,tourney.player.fish.length)}/5 · ${totalInches(tourney.player.fish)} in</b> · <b>${ordinal(playerPlace(tourney))}</b> of ${tourney.rivals.length+1} · <b>${formatRemaining(tourneyRemaining(tourney))}</b> left`});}
function startTournament({key=null,seed=null}={}){if(mode==='demo')takeRod();if(session&&!session.closed)closeCurrentSession();const k=key||dailyKey(clock.ms);const sd=seed||seedFrom(k,'bigbass');tourney=createTournament({seed:sd,spots:demoAdapter.spots()});tourney.key=k;tourney.casts0=angling.state.castCount;reseedPopulation(sd);setWeather(pickWeather(sd,'dawn'));setHour(clock,6.0);setRate('12');hud.hideCard();hud.hideSessionCard();sessionLanded=0;if(!rivalBoats.length)rivalBoats=tourney.rivals.map(()=>makeKayak(scene));rivalBoats.forEach(b=>{b.group.visible=true;});start();applyRealism();updateTourneyBar();hud.toast('Big Bass: twenty minutes at 12x, best five bass by length, against Kim, Dale and Marisol. Photo, measure, release.',8000);return tourney;}
function closeTournament(){if(!tourney||tourney.closed)return;tourneyClose(tourney);tourney.casts=angling.state.castCount-tourney.casts0;angling.reelIn();mode='menu';keys={};touch?.setActive(false);hud.setSession(null);hud.els.hud.classList.add('hidden');rivalBoats.forEach(b=>{b.group.visible=false;});setRate(settings.timeRate==='real'?'real':String(settings.timeRate||4));const st=standings(tourney);const rows=st.map(r=>`${r.place}. ${r.name} ${r.total} in (${r.count} bass)`).join(' · ');cardPost={ns:bigbassNs(tourney.key),score:boardScore(tourney),submitted:false};let ini='';try{ini=localStorage.getItem('first_light_initials')||'';}catch{}sessionBoardMe=null;hud.showSessionCard({title:'Big Bass',summary:tourneySummary(tourney),target:rows,initials:ini,rows:boardRows(null)});const post=cardPost;fetchBoard(post.ns).then(b=>{if(cardPost===post&&!post.submitted)hud.setSessionBoard(boardRows(b,null));});}
function reseedPopulation(seed){for(const f of pop.fish)scene.remove(f.body.root);pop=makePopulation(scene,bathy,cover.features,{seed,assets:assetsById,roster:ROSTER});}
function startSession(variant='dawn',{key=null,seed=null}={}){if(mode==='demo')takeRod();const v=VARIANTS[variant]||VARIANTS.dawn;session=createSession({variant:v.id,key:key||dailyKey(clock.ms),seed});reseedPopulation(session.seed);setWeather(session.weather);setHour(clock,session.startHour);setRate('4');hud.hideCard();hud.hideSessionCard();sessionCasts0=angling.state.castCount;sessionLanded=0;voiceSaid.skunk=false;start();applyRealism();hud.setSession({label:v.label,target:targetName(session),remaining:formatRemaining(remaining(session)),score:0});hud.toast(v.label+': twenty minutes. Target species: '+targetName(session)+'. Three times the points.',7000);return session;}
function closeCurrentSession(){if(!session||session.closed)return;closeSession(session);session.casts=angling.state.castCount-sessionCasts0;angling.reelIn();mode='menu';keys={};touch?.setActive(false);hud.setSession(null);hud.els.hud.classList.add('hidden');const ns=boardNamespace(session);cardPost={ns,score:session.score,submitted:false};let ini='';try{ini=localStorage.getItem('first_light_initials')||'';}catch{}sessionBoardMe=null;hud.showSessionCard({title:(VARIANTS[session.variant]||VARIANTS.dawn).label,summary:sessionSummary(session),target:'Target was '+targetName(session).toLowerCase()+(session.bestTarget?' · you got one':' · none landed'),initials:ini,rows:boardRows(null)});fetchBoard(ns).then(b=>{if(session&&!session.submitted)hud.setSessionBoard(boardRows(b,null));});}
async function submitSession(initials){if(!cardPost||cardPost.submitted)return false;const ini=initialsOf(initials);if(ini.length<1)return false;try{localStorage.setItem('first_light_initials',ini);}catch{}const post=cardPost;post.submitted=true;if(session)session.submitted=true;const ok=await submitScore(post.ns,ini,post.score);if(!ok){post.submitted=false;if(session)session.submitted=false;hud.setSessionBoard('<li class="note">the board did not take that one (busy or offline) · try again in a minute</li>');return false;}sessionBoardMe={name:ini,score:post.score};const b=await fetchBoard(post.ns);hud.setSessionBoard(boardRows(b,sessionBoardMe));return ok;}
function leaveSession(){session=null;tourney=null;cardPost=null;applyRealism();hud.hideSessionCard();hud.showMenu({});}
// --- Species Gallery: the studio fish on a turntable with a size-class slider; 'see it in the lake' follows a live one
let galleryFrom='menu';const gal={id:'largemouth',t:.4,spin:0,dragging:false,lake:null};
const galleryUI=mountGallery({onSelect:id=>galleryShow(id,gal.t),onSlider:t=>galleryShow(gal.id,t),onLake:()=>galleryLake(),onBack:()=>closeGallery()});
function galleryShow(id,t){gal.id=id;gal.t=t;gal.lake=null;const L=lengthForSlider(SPECIES[id],t);setStudio(L,id);galleryUI.setActive(id);galleryUI.setSlider(t);const ev=sunEvents(clock.ms);galleryUI.setCard(galleryCard(id,L,journal,{sunrise:ev.sunrise?hourOf(ev.sunrise):6.5,sunset:ev.sunset?hourOf(ev.sunset):19.5}));}
function stepCoach(dt){
 const on=settings.coach!==false&&mode==='playing'&&!tutorial;
 const ph=angling.state.phase;if(lastAnglingPhase!=='flight'&&ph==='flight'){coachStats.casts++;coachStats.lastCastAt=simTime;const spot=nearestCoverType(kayak.state.x,kayak.state.z);if(spot!==coachStats.lastSpot){coachStats.castsHere=0;coachStats.lastSpot=spot;}coachStats.castsHere++;}
 if(lastAnglingPhase==='retrieve'&&ph==='idle')coachStats.retrieves++;
 coachClock+=dt;if(coachClock<1)return;coachClock=0;
 const ev=sunEvents(clock.ms),sunrise=ev.sunrise?hourOf(ev.sunrise):6.5,sunset=ev.sunset?hourOf(ev.sunset):19.5;
 coachSpots=rankHotspots({features:cover.features,hour:hourOf(clock.ms),sunrise,sunset,cond,activity:activityByHourNow(),caught:Object.fromEntries(journal.catches.map(c=>[c.species,(journal.catches.filter(x=>x.species===c.species).length)]))});
 const kp={x:kayak.state.x,z:kayak.state.z};const top=coachSpots[0]?{...coachSpots[0],...bearingTo(kp,coachSpots[0]),dist:Math.round(Math.hypot(coachSpots[0].x-kp.x,coachSpots[0].z-kp.z))}:null;
 hud.setCoachLine(on&&top?hotspotLine(top):'');
 if(!on)return;
 const lp=angling.lure();const near=(()=>{let best=null,bd=1e9;for(const f of cover.features){const d=Math.hypot(f.x-kp.x,f.z-kp.z);if(d<bd){bd=d;best=f;}}return best?{where:({laydown:'the laydown',dock:'the dock',weedbed:'the weed bed',pads:'the pads',stump:'the stumps',riprap:'the riprap point'})[best.type]||best.type,...bearingTo(kp,best)}:null;})();
 const ctx={enabled:true,phase:ph,idleSeconds:ph==='idle'?simTime-Math.max(coachStats.lastCastAt,coachStats.lastBiteAt,sessionStartAt):0,casts:coachStats.casts,cover:near,lureDepthBed:ph==='retrieve'?bathy.depth(lp.x,lp.z):9,elevation:lastElevation,castsHere:coachStats.castsHere,sinceBite:simTime-Math.max(coachStats.lastBiteAt,sessionStartAt),lure:angling.parts().lure.id,family:angling.parts().lure.family,technique:angling.state.label,retrieves:coachStats.retrieves,missedEarly:coachStats.missedEarly,brokeOff:coachStats.brokeOff,night:lastElevation<-6,unlocked:unlockedRigs(journal),rig:angling.rig().id,hotspot:top};
 const tip=coachTip(coach,ctx,simTime);if(tip){coachStats.lastTip=tip.text;hud.setCaption('Ray: '+tip.text);setTimeout(()=>{if(document.getElementById('caption').textContent==='Ray: '+tip.text)hud.setCaption('');},7000);}
}
let sessionStartAt=0;
// the catch replay: a ghost of the fish retraces the recorded take and fight in slow motion, filmed from below and then from the water
function openReplay({maxSeconds=null}={}){if(!lastReplay||replay)return false;if(!(mode==='playing'||mode==='demo'))return false;if(angling.state.phase!=='landed')return false;replayFrom=mode;tutEvent('replay_open');mode='replay';cameraMode='replay';keys={};pressed={};touch?.setActive(false);hud.hideCard();
 const m=lastReplay.meta;const a=assetsById[m.species];replayGhost=a?makePhotoFishMesh(m.length,a):makeFishMesh(m.length);scene.add(replayGhost.root);replayLure=new T.Mesh(new T.SphereGeometry(.02,8,6),new T.MeshStandardMaterial({color:0x2a2a2a,roughness:.5,metalness:.4}));scene.add(replayLure);
 replay={t:0,cam:null,maxSeconds};document.getElementById('replayBar').classList.remove('hidden');stepReplay(0);return true;}
function closeReplay(){if(mode!=='replay')return false;tutEvent('replay_close');if(replayGhost){scene.remove(replayGhost.root);replayGhost=null;}if(replayLure){scene.remove(replayLure);replayLure=null;}replay=null;document.getElementById('replayBar').classList.add('hidden');mode=replayFrom==='demo'?'demo':'playing';cameraMode='hero';if(mode==='playing'){touch?.setActive(true);if(lastCardShown)hud.showCard(lastCardShown);}return true;}
function stepReplay(dt){if(!replay||!lastReplay)return;replay.t+=dt*REPLAY.slow;const end=replay.maxSeconds!==null?Math.min(lastReplay.duration,replay.maxSeconds*REPLAY.slow):lastReplay.duration;if(replay.t>end+REPLAY.tail){closeReplay();return;}
 const c=replayCamera(lastReplay,Math.min(replay.t,end),(x,z)=>bathy.height(x,z));replay.cam=c;const fr=c.frame;
 if(replayGhost){replayGhost.root.position.set(fr.x,fr.y,fr.z);replayGhost.root.rotation.set(0,fr.heading,0);replayGhost.setSwim(simTime*(fr.state==='RUN'||fr.state==='STRIKE'?9:4),fr.state==='RUN'?.06:.035,0);replayGhost.setJaw(fr.state==='STRIKE'||fr.state==='BITE'?1:.15);replayGhost.setWet(fr.y>-.05?1:0);}
 if(replayLure)replayLure.position.set(fr.lure.x,fr.lure.y,fr.lure.z);
 document.getElementById('replayText').textContent=replayLine(lastReplay,Math.min(replay.t,end),lastReplay.meta.name||'the fish');}
// the lake map: a glass panel over the running lake, from play or the menu
function drawMap(){const c=document.getElementById('mapCanvas');const ctx=c.getContext('2d');const r=lakeMap.draw(ctx,c.width,c.height,{kayak:{x:kayak.state.x,z:kayak.state.z,heading:kayak.state.heading},catches:journal.catches,hour:hourOf(clock.ms),hotspots:settings.coach!==false?coachSpots:[]});document.getElementById('mapLine').textContent=lakeMap.line({x:kayak.state.x,z:kayak.state.z})+(journal.catches.length?` · ${journal.catches.length} in the journal, ${r.spots} spot${r.spots===1?'':'s'}`:' · nothing in the journal yet');return r;}
function openMap(){if(mode==='map'||mode==='demo'||mode==='aquarium'||mode==='gallery'||mode==='photo')return false;mapFrom=mode==='playing'?'playing':'menu';mode='map';tutEvent('map_open');keys={};pressed={};touch?.setActive(false);hud.hideMenu();document.getElementById('mapPanel').classList.remove('hidden');drawMap();return true;}
function closeMap(){if(mode!=='map')return false;tutEvent('map_close');document.getElementById('mapPanel').classList.add('hidden');if(mapFrom==='playing')start();else{mode='menu';hud.showMenu({});}return true;}
function toggleMap(){return mode==='map'?closeMap():openMap();}
function openGallery(id=gal.id,t=gal.t){if(mode==='gallery')return;galleryFrom=mode==='playing'?'playing':'menu';mode='gallery';keys={};pressed={};touch?.setActive(false);hud.hideMenu();hud.els.hud.classList.add('hidden');hud.hideCard();gal.spin=0;gal.dragging=false;galleryUI.show(galleryList(),id,t);galleryShow(id,t);}
